package gadomancymodern.aura;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;

/** Optional integrations are resolved once; their classes are never linked on installations without them. */
public class AuraCompat {
    protected static final java.util.Map<Class<?>,java.util.Optional<WorkbenchAccess>> WORKBENCHES=new java.util.HashMap<>();
    protected static final java.util.Map<Class<?>,java.util.Optional<java.lang.reflect.Method>> CROPS=new java.util.HashMap<>();
    protected record WorkbenchAccess(java.lang.reflect.Field cycle,java.lang.reflect.Field rules,java.lang.reflect.Method state,java.lang.reflect.Method restore,java.lang.reflect.Method threshold,java.lang.reflect.Method heat,java.lang.reflect.Method progress,java.lang.reflect.Method idle,java.lang.reflect.Constructor<?> stateConstructor){}
    public static void coolWorkbench(ServerLevel level,BlockPos at){var tile=level.getBlockEntity(at);if(tile==null||!tile.getClass().getName().equals("automagy.content.GolemWorkbenchBlockEntity"))return;var access=WORKBENCHES.computeIfAbsent(tile.getClass(),type->{try{var cycle=type.getDeclaredField("cycle");var rules=type.getDeclaredField("rules");cycle.setAccessible(true);rules.setAccessible(true);var state=cycle.getType().getMethod("state");var stateType=state.getReturnType();return java.util.Optional.of(new WorkbenchAccess(cycle,rules,state,cycle.getType().getMethod("restore",stateType),rules.getType().getMethod("heatThreshold"),stateType.getMethod("heat"),stateType.getMethod("progress"),stateType.getMethod("idleCoolingTicks"),stateType.getConstructor(int.class,int.class,int.class)));}catch(ReflectiveOperationException failure){org.slf4j.LoggerFactory.getLogger("Gadomancy").warn("Cannot link optional Automagy aura cooling",failure);return java.util.Optional.empty();}});if(access.isEmpty())return;try{var a=access.get();var cycle=a.cycle.get(tile);var state=a.state.invoke(cycle);int heat=(Integer)a.heat.invoke(state);if(heat>(Integer)a.threshold.invoke(a.rules.get(tile))){a.restore.invoke(cycle,a.stateConstructor.newInstance(a.progress.invoke(state),heat-700,a.idle.invoke(state)));tile.setChanged();}}catch(ReflectiveOperationException failure){throw new IllegalStateException("Automagy aura cooling failed",failure);}}
    public static void growCrop(ServerLevel level,BlockPos at){var tile=level.getBlockEntity(at);if(tile==null||!tile.getClass().getName().equals("ttmodern.InfusedCropEntity"))return;var access=CROPS.computeIfAbsent(tile.getClass(),type->{try{return java.util.Optional.of(type.getMethod("tick"));}catch(NoSuchMethodException failure){org.slf4j.LoggerFactory.getLogger("Gadomancy").warn("Cannot link optional Thaumic Tinkerer crop growth",failure);return java.util.Optional.empty();}});if(access.isEmpty())return;try{for(int tick=0;tick<10;tick++)access.get().invoke(tile);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Infused crop aura growth failed",failure);}}
}
